INSERT INTO site_content (id, content_json, updated_at) VALUES ('public', '{"schemaVersion":1,"profilePortraits":{"photo-1534528741775-53994a69daeb":"images/profile-aditi.svg","photo-1500648767791-00dcc994a43e":"images/profile-rohan.svg","photo-1531123897727-8f129e1688ce":"images/profile-nima.svg"},"localPhotos":{"photo-1464822759023-fed622ff2c3b":"images/sandakphu-ridge.jpg","photo-1454496522488-7a8e488e8606":"images/sandakphu-snow.jpg","photo-1551632811-561732d1e306":"images/sandakphu-tonglu-hut.jpg","photo-1500530855697-b586d89ba3ee":"images/darjeeling-teascape.jpg","photo-1470252649378-9c29740c9fa8":"images/darjeeling-tea-garden.jpg","photo-1511497584788-876760111969":"images/darjeeling-kanchenjunga.jpg","photo-1470770841072-f978cf4d019e":"images/sikkim-tsomgo.jpg","photo-1482938289607-e9573fc25ebb":"images/sikkim-tsomgo-mist.jpg","photo-1448375240586-882707db888b":"images/sikkim-enchey-monastery.jpg","photo-1516026672322-bc52d61a55d5":"images/sikkim-rumtek-monastery.jpg","photo-1464278533981-50106e6176b1":"images/kashmir-dal-lake.jpg","photo-1500534623283-312aade485b7":"images/kashmir-baisaran.jpg","photo-1501785888041-af3ef285b470":"images/kashmir-pahalgam-trail.jpg","photo-1472396961693-142e6e269027":"images/himachal-baspa-valley.jpg","photo-1441974231531-c6227db76b6e":"images/himachal-barshaini.jpg","photo-1473448912268-2022ce9509d8":"images/himachal-manali-mountains.jpg","photo-1519681393784-d120267933ba":"images/himachal-key-monastery.jpg","photo-1470071459604-3b5ec3a7fe05":"images/himachal-spiti-river.jpg","photo-1433086966358-54859d0ed716":"images/sikkim-tsomgo-mist.jpg","photo-1486870591958-9b9d0d1dda99":"images/sandakphu-ridge.jpg","photo-1500534314209-a25ddb2bd429":"images/darjeeling-tea-garden.jpg","photo-1523712999610-f77fbcfc3843":"images/sikkim-rumtek-monastery.jpg","photo-1483728642387-6c3bdd6c93e5":"images/himachal-manali-mountains.jpg","photo-1494783367193-149034c05e8f":"images/sandakphu-snow.jpg","photo-1510798831971-661eb04b3739":"images/himachal-key-monastery.jpg"},"trips":[{"slug":"sandakphu","title":"Sandakphu: the trail above the clouds","category":"Trekking","region":"West Bengal","destinations":["sandakphu"],"seasons":["oct-dec","jan-mar"],"styles":["Trekking"],"level":"Moderate","image":"images/sandakphu-ridge.jpg","description":"Trace the high ridge above Singalila, with long views toward the Himalayan range and quiet stops in mountain settlements.","badge":"High ridge"},{"slug":"sandakphu-village-trail","title":"Singalila ridge and quiet villages","category":"Trekking","region":"West Bengal","destinations":["sandakphu"],"seasons":["oct-dec","jan-mar"],"styles":["Trekking"],"level":"Easy","image":"images/sandakphu-tonglu-hut.jpg","description":"Take a gentler route through forest paths and ridge-top settlements near Sandakphu, with time to pause between walks.","badge":"Gentle pace"},{"slug":"sikkim","title":"Sikkim, slowly","category":"Culture & nature","region":"Sikkim","destinations":["sikkim"],"seasons":["oct-dec","jan-mar","apr-jun"],"styles":["Culture & nature"],"level":"Easy","image":"images/sikkim-enchey-monastery.jpg","description":"Explore monastery courtyards, mountain villages, and the quieter roads of the eastern Himalayas.","badge":"Monastery routes"},{"slug":"sikkim-village-walk","title":"Sikkim village walks and monastery stays","category":"Culture & nature","region":"Sikkim","destinations":["sikkim"],"seasons":["oct-dec","jan-mar","apr-jun"],"styles":["Culture & nature"],"level":"Moderate","image":"images/sikkim-rumtek-monastery.jpg","description":"Build a journey around village trails, local food, and time to learn about the region''s living traditions.","badge":"Village routes"},{"slug":"darjeeling","title":"Tea trails & Darjeeling mornings","category":"Weekend escape","region":"Darjeeling","destinations":["darjeeling"],"seasons":["oct-dec","jan-mar","apr-jun"],"styles":["Weekend escape"],"level":"Easy","image":"images/darjeeling-teascape.jpg","description":"Walk among tea gardens, explore old hill-town lanes, and make room for an unhurried morning.","badge":"Tea garden walk"},{"slug":"darjeeling-tea-country","title":"Darjeeling tea country by foot","category":"Weekend escape","region":"Darjeeling","destinations":["darjeeling"],"seasons":["oct-dec","jan-mar","apr-jun"],"styles":["Weekend escape"],"level":"Moderate","image":"images/darjeeling-tea-garden.jpg","description":"Follow paths through tea country and hillside lanes, with time to meet local growers and hosts along the way.","badge":"Tea garden walk"},{"slug":"kashmir","title":"Kashmir, the great outdoors","category":"Nature escape","region":"Kashmir","destinations":["kashmir"],"seasons":["apr-jun"],"styles":["Culture & nature"],"level":"Easy","image":"images/kashmir-dal-lake.jpg","description":"Spend time beside clear lakes and open meadows, and take the valley at a pace that leaves room for local encounters.","badge":"Valley landscape"},{"slug":"kashmir-meadows","title":"Kashmir meadow and lake escape","category":"Nature escape","region":"Kashmir","destinations":["kashmir"],"seasons":["apr-jun","oct-dec"],"styles":["Culture & nature"],"level":"Moderate","image":"images/kashmir-baisaran.jpg","description":"Pair lakeside pauses with walks through the valley''s changing landscapes and seasonal meadows.","badge":"Lakes & meadows"},{"slug":"himachal","title":"Himachal beyond the postcards","category":"Mountain journey","region":"Himachal Pradesh","destinations":["himachal"],"seasons":["oct-dec","jan-mar","apr-jun"],"styles":["Trekking"],"level":"Moderate","image":"images/himachal-baspa-valley.jpg","description":"Take the scenic way through pine forests, rivers, and mountain hamlets, with stops shaped around the route and conditions.","badge":"Pine forest route"},{"slug":"himachal-forest-paths","title":"Pine forest paths of Himachal","category":"Mountain journey","region":"Himachal Pradesh","destinations":["himachal"],"seasons":["oct-dec","jan-mar","apr-jun"],"styles":["Trekking"],"level":"Easy","image":"images/himachal-barshaini.jpg","description":"Start with a relaxed mountain walk through pine woods and riverside villages, with room to find your own rhythm.","badge":"Forest walk"},{"slug":"weekend","title":"A little further into the hills","category":"Weekend escape","region":"North Bengal","destinations":["darjeeling"],"seasons":["oct-dec","jan-mar","apr-jun"],"styles":["Weekend escape"],"level":"Easy","image":"images/darjeeling-kanchenjunga.jpg","description":"Step away from the usual routine for a short hill-country escape built around fresh air, local food, and unhurried time.","badge":"Short escape"}],"articles":[{"title":"How to prepare for your first Himalayan trek","category":"Trail notes","read":"7 min read","author":"TREKKING Journal","image":"images/himachal-key-monastery.jpg","excerpt":"A practical guide to choosing a route, building confidence on local walks, and preparing for changing mountain conditions."},{"title":"The quiet magic of a Darjeeling dawn","category":"Slow travel","read":"5 min read","author":"TREKKING Journal","image":"images/darjeeling-kanchenjunga.jpg","excerpt":"Explore tea country in the softer hours of the day, when hillside paths and old lanes invite a slower pace."},{"title":"A local''s guide to Sikkim''s monastery trails","category":"Culture","read":"6 min read","author":"TREKKING Journal","image":"images/sikkim-enchey-monastery.jpg","excerpt":"A thoughtful visitor''s guide to approaching monastery paths with curiosity, care, and respect for local customs."},{"title":"What to pack for a changing mountain forecast","category":"Trail notes","read":"4 min read","author":"TREKKING Journal","image":"images/himachal-spiti-river.jpg","excerpt":"Use a flexible layering system, protect essentials from rain, and leave space for the conditions you cannot predict."},{"title":"Why we travel in smaller groups","category":"Our approach","read":"5 min read","author":"TREKKING Journal","image":"images/sikkim-rumtek-monastery.jpg","excerpt":"Smaller groups can make it easier to adapt a day''s pace, listen to local guides, and leave room for conversation."},{"title":"Five beautiful weekends in the hills","category":"Inspiration","read":"6 min read","author":"TREKKING Journal","image":"images/sikkim-tsomgo-mist.jpg","excerpt":"Ideas for a short change of scene, from tea-country walks to quiet forest paths and lakeside pauses."}],"destinations":[{"title":"Sandakphu","sub":"West Bengal · India","image":"images/sandakphu-ridge.jpg","aboutImage":"images/sandakphu-snow.jpg","slug":"sandakphu"},{"title":"Darjeeling","sub":"West Bengal · India","image":"images/darjeeling-teascape.jpg","aboutImage":"images/darjeeling-kanchenjunga.jpg","slug":"darjeeling"},{"title":"Sikkim","sub":"Eastern Himalayas","image":"images/sikkim-tsomgo.jpg","aboutImage":"images/sikkim-enchey-monastery.jpg","slug":"sikkim"},{"title":"Kashmir","sub":"Northern India","image":"images/kashmir-dal-lake.jpg","aboutImage":"images/kashmir-baisaran.jpg","slug":"kashmir"},{"title":"Himachal Pradesh","sub":"Western Himalayas","image":"images/himachal-baspa-valley.jpg","aboutImage":"images/himachal-key-monastery.jpg","slug":"himachal"}],"customerReviews":[{"name":"S. Spence","initials":"SS","image":"images/profile-rohan.svg","rating":5,"summary":"Said the self-guided route and arrangements matched their group’s needs and went smoothly.","journey":"8-day Val Maira self-guided hike","source":"https://www.trustpilot.com/reviews/6ab933c47048e6a70f35957f"},{"name":"Benedetta","initials":"B","image":"images/profile-aditi.svg","rating":4.5,"summary":"Enjoyed a challenging Gran Paradiso hike, scenic views, welcoming hospitality, and good food in the mountain huts.","journey":"Gran Paradiso four-day hike","source":"https://www.trustpilot.com/reviews/6aa91756a2bd03766f9054d6"},{"name":"D. Karimi","initials":"DK","image":"images/profile-nima.svg","rating":4,"summary":"Praised the guide, beautiful hike, food, and warm group atmosphere.","journey":"Italian Alps hike","source":"https://www.trustpilot.com/reviews/6aa6d01babd334626046af8c"},{"name":"Sarah Hickey","initials":"SH","image":"images/profile-aditi.svg","rating":4.8,"summary":"Described a well-planned family trek with balanced routes, dependable transfers, comfortable stays, and thoughtful support.","journey":"Val d’Ayas & Monterosa week-long hut-to-hut trek","source":"https://www.trustpilot.com/reviews/6a82654ac0c6422cf8619d9f"},{"name":"Cindy Carpenter","initials":"CC","image":"images/profile-rohan.svg","rating":4.2,"summary":"Said a custom Val Maira route fit the group’s requested dates, distance, and elevation, with arrangements running smoothly.","journey":"Five-day Val Maira hike","source":"https://www.trustpilot.com/reviews/6a6f54d3e25b98b2466aef43"},{"name":"Egle Tiskeviciute","initials":"ET","image":"images/profile-nima.svg","rating":3.5,"summary":"Enjoyed a Susa Valley hut-to-hut trek and highlighted the guide’s care, communication, local stories, and wildlife.","journey":"Four-day Susa Valley Ring Trek","source":"https://www.trustpilot.com/reviews/6a67797f698c7a0ca57ad9bd"}],"legalData":{"privacy":{"title":"Privacy policy","intro":"Your trust matters to us. Here''s how we handle the information you share when exploring or booking a TREKKING journey.","sections":[["Information we collect","We may collect contact details and trip preferences that you choose to share through our forms or booking enquiries. Payment information is handled by the payment provider you select; please review that provider''s privacy notice."],["How we use information","We use information to respond to enquiries, coordinate requested travel arrangements, provide customer support, and improve this website. We do not sell personal information."],["Cookies and tracking","This website may use essential cookies for basic functionality. Optional analytics or marketing technologies should only be enabled with your consent where required."],["Third-party services","Maps, payment providers, social networks and other external services may process data under their own privacy policies. We only share information needed to fulfil a service you request."],["Data security and retention","We use reasonable safeguards and retain information only for as long as needed for the purpose collected or as required by applicable law. No online transmission can be guaranteed completely secure."],["Your choices and rights","Depending on where you live, you may have rights to access, correct or request deletion of personal information. Contact us using the details below to make a request."],["Contact","Use the contact form to prepare a privacy question. The form must be connected to an approved business contact before submissions can be received."]]},"terms":{"title":"Terms & conditions","intro":"These terms explain the basics of using our website and enquiring about or booking a journey. Please read them before confirming a trip.","sections":[["Using this website","Use the site lawfully and do not interfere with its operation or attempt to access systems or information that are not intended for you."],["Bookings and confirmation","A booking is confirmed only when we provide written confirmation and the required payment has been received. Enquiries and itinerary requests are not confirmed bookings."],["Pricing and availability","Prices, departure dates and availability can change until a booking is confirmed. Any inclusions, exclusions and taxes will be stated in the applicable trip details and confirmation."],["Payments","Payment schedules and accepted methods will be shared before booking. Do not send payment details through unsecured messages. Applicable payment provider terms also apply."],["Customer responsibilities","Travellers are responsible for providing accurate details, carrying valid identification and travel documents, and following local laws and reasonable guidance from trip leaders."],["Travel requirements and safety","Check entry rules, health guidance, insurance needs and fitness requirements for your trip. Adventure travel carries inherent risks; review the trip-specific information before booking."],["Changes and cancellation","Changes, cancellations and refunds are governed by the cancellation policy and the terms included in your booking confirmation."],["Liability and intellectual property","To the extent permitted by law, website content is provided for general information. Website text, design and brand assets may not be reused without permission."]]},"cancellation":{"title":"Cancellation & refund policy","intro":"Plans can change. This policy describes how cancellation requests and company-initiated changes are handled. Your booking confirmation may contain trip-specific terms.","sections":[["Requesting a cancellation","Use the contact form to prepare a written request and include your booking reference. No request is received until the website is connected to a business communication service."],["Customer cancellations","Any cancellation charges or refundable amount depend on the trip, notice period, and non-recoverable costs already committed. The exact schedule must be shown in your booking confirmation before payment."],["Company cancellations","If we cancel a departure, we will contact affected travellers with available options. Any refund or alternative arrangements will follow the terms provided for that trip and applicable law."],["Refund processing","Approved refunds are returned using the original payment method where possible. Processing time can depend on the payment provider; we will communicate the expected timeline when confirming a refund."],["Rescheduling","Date changes depend on availability and may involve a price adjustment or supplier charges. Contact us as early as possible to discuss options."],["No-shows and late arrivals","Missing a departure or arriving too late to join may be treated as a cancellation and may not be refundable. Contact the trip coordinator as soon as possible if delayed."],["Force majeure","Severe weather, access restrictions, safety concerns and other circumstances outside reasonable control may require itinerary changes or cancellation. We will explain available options under your booking terms."]]},"disclaimer":{"title":"Travel disclaimer","intro":"Mountain travel is rewarding, but conditions and plans can change. Please use trip information as a guide and make informed decisions.","sections":[["Information accuracy","We take care to keep website information useful and current, but routes, opening times, prices and conditions may change. Confirm important details with us before travel."],["Weather and environment","Weather, altitude, terrain and local conditions are unpredictable. Itineraries may change to protect traveller and community safety."],["Itinerary changes","Trip leaders may adjust plans in response to conditions, access, health, local advice or other operational needs. A published itinerary is an outline, not a guarantee of every activity."],["Third-party providers","Some services may be provided by independent accommodation, transport or activity partners, subject to their own terms and operating conditions."],["Personal responsibility and adventure risk","Outdoor activities involve inherent risks. Travellers should assess their fitness, follow safety guidance, disclose relevant needs and obtain suitable travel insurance."]]},"cookies":{"title":"Cookie policy","intro":"This page explains the small data files and similar technologies this website may use, and how you can manage your choices.","sections":[["What cookies are","Cookies are small files stored by your browser. Similar technologies can remember preferences or help a website understand how it is used."],["Essential cookies","Essential cookies support core site functions such as navigation and security. They cannot be switched off through our site preferences."],["Analytics cookies","If enabled, analytics cookies help us understand aggregated website use and improve pages. They should remain disabled until you consent where required."],["Marketing cookies","Marketing cookies may be used to measure campaigns or tailor promotions. We do not enable optional marketing cookies without the appropriate consent."],["Managing preferences","You can use browser settings to view, block or delete cookies. Blocking some cookies may affect site functionality. Use the cookie settings control on this site to update optional preferences."],["Contact","Use the contact form to prepare a question about this policy. No message is sent until the website is connected to a business communication service."]]}},"assets":{"images/.DS_Store":"images/.DS_Store","images/cinematic-video.mp4":"images/cinematic-video.mp4","images/darjeeling-kanchenjunga.jpg":"images/darjeeling-kanchenjunga.jpg","images/darjeeling-tea-garden.jpg":"images/darjeeling-tea-garden.jpg","images/darjeeling-teascape.jpg":"images/darjeeling-teascape.jpg","images/favicon.svg":"images/favicon.svg","images/himachal-barshaini.jpg":"images/himachal-barshaini.jpg","images/himachal-baspa-valley.jpg":"images/himachal-baspa-valley.jpg","images/himachal-key-monastery.jpg":"images/himachal-key-monastery.jpg","images/himachal-manali-mountains.jpg":"images/himachal-manali-mountains.jpg","images/himachal-spiti-river.jpg":"images/himachal-spiti-river.jpg","images/IMAGE-CREDITS.md":"images/IMAGE-CREDITS.md","images/kashmir-baisaran.jpg":"images/kashmir-baisaran.jpg","images/kashmir-dal-lake.jpg":"images/kashmir-dal-lake.jpg","images/kashmir-pahalgam-trail.jpg":"images/kashmir-pahalgam-trail.jpg","images/logo.svg":"images/logo.svg","images/profile-aditi.svg":"images/profile-aditi.svg","images/profile-nima.svg":"images/profile-nima.svg","images/profile-rohan.svg":"images/profile-rohan.svg","images/sandakphu-ridge.jpg":"images/sandakphu-ridge.jpg","images/sandakphu-snow.jpg":"images/sandakphu-snow.jpg","images/sandakphu-tonglu-hut.jpg":"images/sandakphu-tonglu-hut.jpg","images/sikkim-enchey-monastery.jpg":"images/sikkim-enchey-monastery.jpg","images/sikkim-rumtek-monastery.jpg":"images/sikkim-rumtek-monastery.jpg","images/sikkim-tsomgo-mist.jpg":"images/sikkim-tsomgo-mist.jpg","images/sikkim-tsomgo.jpg":"images/sikkim-tsomgo.jpg"}}', datetime('now')) ON CONFLICT(id) DO UPDATE SET content_json = excluded.content_json, updated_at = excluded.updated_at;
